async function processWithHeartbeat(
  queueUrl: string,
  receiptHandle: string,
  work: () => Promise<void>,
) {
  const interval = setInterval(() => {
    sqs.send(new ChangeMessageVisibilityCommand({
      QueueUrl: queueUrl,
      ReceiptHandle: receiptHandle,
      VisibilityTimeout: 120,
    })).catch(console.error);
  }, 60_000);
  try {
    await work();
  } finally {
    clearInterval(interval);
  }
}
